select

from survey_investigator
where id = #{id,jdbcType=BIGINT}

select

from survey_investigator
where user_id = #{userId,jdbcType=BIGINT} limit 1;

select a.id as id, a.nick_name as nickName, a.real_name as realName, a.user_id as userId, a.tel as tel, a.org_id as orgId, a.org_name as orgName, a.type as type from survey_investigator a left join bus_user_role b on a.user_id = b.user_id where a.delete_flag=0 and b.role_id = #{roleId,jdbcType=BIGINT}
and a.org_id in (select id from survey_franchisee where id = #{orgId,jdbcType=BIGINT} or parent_id = #{orgId,jdbcType=BIGINT})
order by a.id desc

SELECT aa.*,IFNULL(bb.opinionPoll,0) opinionPoll,IFNULL(cc.overdue,0) overdue FROM ( select a.id as id, a.nick_name as nickName, a.real_name as realName, a.user_id as userId, a.tel as tel, a.org_id as orgId, a.org_name as orgName, a.type as type from survey_investigator a left join bus_user_role b on a.user_id = b.user_id where a.delete_flag=0 and b.role_id = #{roleId,jdbcType=BIGINT}
and a.org_id in (select id from survey_franchisee where id = #{orgId,jdbcType=BIGINT} or parent_id = #{orgId,jdbcType=BIGINT})
and a.survey_area_id=#{surveyAreaId}
and a.user_id=#{userId}
order by a.id desc ) aa LEFT JOIN ( SELECT a.survey_user_id,COUNT(1) opinionPoll FROM survey_investigator_case a LEFT JOIN survey_risk_case_info b ON a.survey_info_id=b.id WHERE a.survey_state = 1 AND a.delete_flag=0 AND b.delete_flag = 0 GROUP BY a.survey_user_id ) bb ON aa.userId=bb.survey_user_id LEFT JOIN ( SELECT a.survey_user_id,COUNT(1) overdue FROM survey_investigator_case a LEFT JOIN survey_risk_case_info b ON a.survey_info_id=b.id WHERE a.delete_flag=0 AND b.delete_flag = 0 AND a.aging_day < 0 AND a.survey_state = 1 GROUP BY a.survey_user_id ) cc ON aa.userId=cc.survey_user_id

SELECT aa.id,aa.user_id as userId,aa.real_name as realName,aa.org_name as orgName,aa.tel,aa.create_time as createTime, IFNULL(score,0) score,aa.real_qualified_time as realQualifiedTime,aa.qualified_enfd_time as qualifiedEnfdTime, aa.effec_days as effecDays,aa.teacher_user_name as teacherUserName,aa.teacher_org_name as teacherOrgName, aa.teacher_user_tel as teacherUserTel,aa.teacher_reward as teacherReward,aa.teacher_real_reward as teacherRealReward, aa.reward_desc as rewardDesc,aa.is_new_people as isNewPeople,aa.operate_user_name as operateUserName,aa.operate_time as operateTime FROM survey_investigator aa LEFT JOIN ( SELECT a.survey_user_id,IFNULL(SUM(a.score),0) score FROM survey_investigator_case a LEFT JOIN survey_risk_case_info b ON a.survey_info_id=b.id LEFT JOIN survey_assign_org c ON a.survey_assorg_case_id = c.id LEFT JOIN survey_consignor d ON a.entrust_org_id=d.id WHERE a.delete_flag=0 AND b.delete_flag=0 AND c.delete_flag=0 AND d.delete_flag=0 AND d.org_attr =2 GROUP BY a.survey_user_id ) bb ON aa. user_id=bb.survey_user_id
aa.delete_flag=0 and (aa.bus_type = 1 or aa.bus_type = 3 )
and aa.user_id in (${userId})
and aa.org_id in (${orgId})
and teacher_user_id in (${teacherUserId})
and qualified_enfd_time >= #{startClosingTime}
and qualified_enfd_time <= #{endClosingTime}
and is_new_people=#{isNewPeople}
limit #{pageIndex}, #{pageSize}

SELECT * FROM survey_investigator i LEFT JOIN bus_user_role r ON i.user_id = r.user_id WHERE i.delete_flag = 0 AND r.role_id = 50
AND FIND_IN_SET( i.org_id, (SELECT GROUP_CONCAT(id) FROM survey_franchisee WHERE parent_id = #{orgId} or id= #{orgId}))
AND i.org_id = #{orgId}

